function mediaTile(resource) {
  const labels = text.knowledgeCard;
  const embedSrc = resource.youtubeVideoId
    ? `https://www.youtube.com/embed/${resource.youtubeVideoId}`
    : resource.youtubePlaylistId
      ? `https://www.youtube.com/embed/videoseries?list=${resource.youtubePlaylistId}`
      : "";
  const youtubeHref = resource.youtubeVideoId
    ? `https://www.youtube.com/watch?v=${resource.youtubeVideoId}`
    : resource.youtubePlaylistId
      ? `https://www.youtube.com/playlist?list=${resource.youtubePlaylistId}`
      : "";

  return `
    <div class="media-tile ${resource.pending ? "media-tile--pending" : ""}">
      <div class="media-meta">
        <span>${(MEDIA_CATEGORY_EN[resource.category]||resource.category)} · ${translateScope(resource.scope)}</span>
        <strong>${translateMediaTitle(resource.title)}</strong>
      </div>
      ${embedSrc ? `
        <div class="youtube-embed">
          <iframe
            src="${embedSrc}"
            title="${translateMediaTitle(resource.title)}"
            loading="lazy"
            referrerpolicy="strict-origin-when-cross-origin"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            allowfullscreen
          ></iframe>
        </div>
        <a class="media-link" href="${youtubeHref}" target="_blank" rel="noreferrer">${labels.youtubeOpen}</a>
      ` : `
        <div class="media-placeholder">
          <strong>${labels.linkPending}</strong>
          <p>${labels.linkPendingText}</p>
        </div>
      `}
    </div>
  `;
}

function profilePage() {
  const allCodes = Object.keys(subtypeProfiles);
  const sortBy = (order) => (a, b) => order.indexOf(parseInt(a[2])) - order.indexOf(parseInt(b[2]));
  const groups = [
    { label: "Body Centre · Type 8, 9, 1", hint: "Action, instinct, body",   codes: allCodes.filter(c => [8,9,1].includes(parseInt(c[2]))).sort(sortBy([8,9,1])) },
    { label: "Heart Centre · Type 2, 3, 4", hint: "Feeling, relationship, identity", codes: allCodes.filter(c => [2,3,4].includes(parseInt(c[2]))).sort(sortBy([2,3,4])) },
    { label: "Kopfzentrum · Typ 5, 6, 7",  hint: "Denken, Sicherheit, Vorstellung", codes: allCodes.filter(c => [5,6,7].includes(parseInt(c[2]))).sort(sortBy([5,6,7])) },
  ];
  const current = state.profile.id;
  const firstVisit = state.isFirstVisit;

  let cardIdx = 0;
  const groupsHTML = groups.map(g => {
    const cardsHTML = g.codes.map(id => {
      const p = subtypeProfiles[id];
      const active = id === current ? ' profile-card--active' : '';
      const delay = (cardIdx++ * 0.035).toFixed(3);
      const tc = typeColorFromCode(p.code);
      return `<button class="profile-card${active}" style="animation-delay:${delay}s" data-select-profile="${id}">
        <div class="profile-card__visual" style="position:relative;border-radius:50%;overflow:hidden;box-shadow:0 0 0 3px ${tc};">
          ${p.image
            ? `<img src="${p.image}" alt="${p.archetype_en || p.archetype || p.code}" class="profile-card__img" style="position:absolute;inset:0;width:140%;height:140%;margin:-20%;object-fit:cover;border-radius:0;animation:none;" />`
            : `<span class="profile-card__emoji">${p.emoji || ''}</span>`}
        </div>
        <span class="profile-card__code" style="color:${tc};">${enCode(p.code)}</span>
        <strong class="profile-card__title">${p.title_en || p.title}</strong>
        ${p.titleAlt ? `<em class="profile-card__alt">${TITLEALT_EN[p.titleAlt] || p.titleAlt}</em>` : ''}
        ${p.variant ? `<span class="profile-card__variant">${VARIANT_EN[p.variant] || p.variant}</span>` : ''}
      </button>`;
    }).join("");
    return `<section class="profile-group">
      <div class="profile-group__head">
        <h2 class="profile-group__label">${g.label}</h2>
        <span class="profile-group__hint">${g.hint}</span>
      </div>
      <div class="profile-grid">${cardsHTML}</div>
    </section>`;
  }).join("");

  return shell(`
    ${firstVisit ? '' : pageHeader("profile")}
    <section class="narrow centered profile-intro">
      ${firstVisit ? `<div class="profile-intro__compass">${compassMark("small")}</div>` : ''}
      <h1>${firstVisit ? 'Which Subtype are you?' : 'Choose Subtype'}</h1>
      <p class="lead-small">${firstVisit
        ? 'Select your Enneagram Subtype. The Compass aligns fully to you — daily impulse, patterns, tools and healing path.'
        : 'Your current profile is <strong>' + enCode(state.profile.code) + ' · ' + state.profile.title + '</strong>. Choose a different Subtype to realign the Compass.'
      }</p>
      <p class="profile-type-hint">Don't know your Subtype yet? No problem — look at the three variants of your type (e.g. SP6, SO6, SX6) and choose the one that feels most resonant.</p>
    </section>
    ${groupsHTML}
    ${firstVisit ? `<p class="profile-skip">Not sure yet? <button class="ghost-link" data-route="knowledge">Explore the Knowledge Atlas first</button></p>` : ''}
  `);
}

